329	async function allChunksValid(eff) {
330	  const n = chunkCount(eff);
331	  for (let i = 0; i < n; i++) {
332	    if (!eff.chunks[i]) return false;
333	    if (!(await fileValid(eff.id, i, eff.chunks[i]))) return false;
334	  }
335	  return true;
336	}
