338	async function fileValid(id, i, info) {
339	  try {
340	    const st = await fs.stat(chunkPath(id, i));
341	    if (st.size !== info.bytes) return false;
342	    return (await sha256File(chunkPath(id, i))) === info.sha256;
343	  } catch {
344	    return false;
345	  }
346	}
