352	export async function assembleHex(eff) {
353	  const h = createHash('sha256');
354	  let bytes = 0;
355	  const n = chunkCount(eff);
356	  for (let i = 0; i < n; i++) {
357	    const info = eff.chunks[i];
358	    if (!info) throw new Error(`missing chunk ${i} for ${eff.id}`);
359	    const buf = await fs.readFile(chunkPath(eff.id, i));
360	    if (buf.length !== info.bytes) throw new Error(`chunk ${i} length mismatch for ${eff.id}`);
361	    h.update(buf);
362	    bytes += buf.length;
363	  }
364	  return { sha256: h.digest('hex'), bytes };
365	}
