367	export async function assembleToFile(eff, dest) {
368	  await fs.mkdir(path.dirname(dest), { recursive: true });
369	  const out = await fs.open(dest, 'w');
370	  try {
371	    const n = chunkCount(eff);
372	    for (let i = 0; i < n; i++) {
373	      const info = eff.chunks[i];
374	      if (!info) throw new Error(`missing chunk ${i} for ${eff.id}`);
375	      const buf = await fs.readFile(chunkPath(eff.id, i));
376	      if (buf.length !== info.bytes) throw new Error(`chunk ${i} length mismatch for ${eff.id}`);
377	      await out.write(buf);
378	    }
379	  } finally {
380	    await out.close();
381	  }
382	}
