504	async function buildContiguousPrefix(id, chunks, chunkSize) {
505	  const parts = [];
506	  let bytes = 0;
507	  for (let i = 0; ; i++) {
508	    if (!chunks[i]) break;
509	    const buf = await fs.readFile(chunkPath(id, i)).catch(() => null);
510	    if (!buf || buf.length !== chunks[i].bytes) break;
511	    if (sha256Buf(buf) !== chunks[i].sha256) break;
512	    parts.push(buf);
513	    bytes += buf.length;
514	    if (bytes >= CONFIG.gitPartialMaxBytesPerFile) break;
515	  }
516	  if (parts.length === 0) return null;
517	  return { buffer: Buffer.concat(parts), bytes, chunkCount: parts.length };
518	}
