 31	function makeServer(content, opts = {}) {
 32	  const state = { etag: opts.etag || '"v1"', dropAfter: opts.dropAfter ?? null, ignoreRange: !!opts.ignoreRange };
 33	  const server = http.createServer((req, res) => {
 34	    const range = req.headers.range;
 35	    const ifRange = req.headers['if-range'];
 36	    const ifRangeOk = !ifRange || ifRange === state.etag;
 37	    let start = 0;
 38	    let end = content.length - 1;
 39	    let status = 200;
 40	    if (range && !state.ignoreRange && ifRangeOk) {
 41	      const m = /bytes=(\d+)-(\d*)/.exec(range);
 42	      if (m) {
 43	        start = Number(m[1]);
 44	        end = m[2] ? Number(m[2]) : content.length - 1;
 45	        if (start >= content.length) {
 46	          res.writeHead(416, { 'Content-Range': `bytes */${content.length}` });
 47	          res.end();
 48	          return;
 49	        }
 50	        end = Math.min(end, content.length - 1);
 51	        status = 206;
 52	      }
 53	    }
 54	    const body = content.subarray(start, end + 1);
 55	    const headers = { ETag: state.etag, 'Last-Modified': 'Wed, 01 Jan 2020 00:00:00 GMT' };
 56	    if (status === 206) headers['Content-Range'] = `bytes ${start}-${end}/${content.length}`;
 57	    headers['Content-Length'] = String(status === 206 ? body.length : content.length);
 58	    res.writeHead(status, headers);
 59	    if (state.dropAfter != null) {
 60	      res.write(body.subarray(0, state.dropAfter));
 61	      setTimeout(() => res.socket.destroy(), 5);
 62	      return;
 63	    }
 64	    res.end(body);
 65	  });
 66	  return new Promise((resolve) => {
 67	    server.listen(0, '127.0.0.1', () => {
 68	      resolve({
 69	        url: `http://127.0.0.1:${server.address().port}/file.bin`,
 70	        state,
 71	        close: () => new Promise((r) => server.close(r)),
 72	      });
 73	    });
 74	  });
 75	}
