// Throttled, resumable HTTP range downloads.
//
// Design notes (defects these guard against):
//  * A single origin connection delivers only ~20 KiB/s, so the pool runs
//    several connections while an aggregate token bucket caps total bandwidth.
//  * The origin drops connections and can stall; we use idle + attempt
//    timeouts and bounded retries with jittered backoff and Retry-After.
//  * A server that ignores Range returns 200. We must never append that full
//    body onto an existing partial; the caller gets a typed RangeIgnored error
//    and restarts the file from zero.

import https from 'node:https';
import http from 'node:http';
import { createWriteStream } from 'node:fs';
import { promises as fs } from 'node:fs';

export const sleep = (ms) => new Promise((r) => setTimeout(r, Math.max(0, ms)));

// A cooperative cancellation error. It is distinct from transient/validator
// errors so callers can preserve already-verified chunks on ordinary abort.
export function abortError(reason = 'aborted') {
  const e = new Error(reason);
  e.name = 'AbortError';
  e.aborted = true;
  return e;
}

export function jitter(ms, ratio = 0.3) {
  const d = ms * ratio;
  return Math.round(ms - d + Math.random() * (2 * d));
}

// ---------------------------------------------------------------------------
// Aggregate token bucket
// ---------------------------------------------------------------------------

export function createRateLimiter(bytesPerSecond) {
  let tokens = bytesPerSecond; // allow a small initial burst
  let last = Date.now();
  const refill = () => {
    const now = Date.now();
    if (now > last) {
      tokens = Math.min(bytesPerSecond, tokens + ((now - last) / 1000) * bytesPerSecond);
      last = now;
    }
  };
  return {
    async take(n) {
      if (!bytesPerSecond || bytesPerSecond <= 0) return;
      let remaining = n;
      while (remaining > 0) {
        refill();
        if (tokens >= remaining) {
          tokens -= remaining;
          return;
        }
        const need = remaining - tokens;
        await sleep(Math.max(5, Math.ceil((need / bytesPerSecond) * 1000)));
      }
    },
  };
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class TransientError extends Error {
  constructor(msg, { retryAfterMs, status } = {}) {
    super(msg);
    this.name = 'TransientError';
    this.transient = true;
    this.retryAfterMs = retryAfterMs;
    this.status = status;
  }
}
export class RangeIgnoredError extends Error {
  constructor(msg) {
    super(msg);
    this.name = 'RangeIgnoredError';
    this.rangeIgnored = true;
  }
}
export class RangeMismatchError extends Error {
  constructor(msg) {
    super(msg);
    this.name = 'RangeMismatchError';
    this.rangeMismatch = true;
  }
}
export class RangeNotSatisfiableError extends Error {
  constructor(msg) {
    super(msg);
    this.name = 'RangeNotSatisfiableError';
    this.rangeNotSatisfiable = true;
  }
}
export class PermanentError extends Error {
  constructor(msg, status) {
    super(msg);
    this.name = 'PermanentError';
    this.status = status;
  }
}

export function parseContentRange(value) {
  if (!value) return null;
  const m = /^bytes\s+(\d+)-(\d+)\/(\d+|\*)$/i.exec(value.trim());
  if (!m) return null;
  return { start: Number(m[1]), end: Number(m[2]), total: m[3] === '*' ? null : Number(m[3]) };
}

function retryAfterToMs(headers) {
  const ra = headers['retry-after'];
  if (!ra) return undefined;
  const secs = Number(ra);
  if (Number.isFinite(secs)) return secs * 1000;
  const when = Date.parse(ra);
  if (Number.isFinite(when)) return Math.max(0, when - Date.now());
  return undefined;
}

// ---------------------------------------------------------------------------
// One streaming GET
// ---------------------------------------------------------------------------

// Issues a GET. When destTmp is provided the (possibly partial) body is written
// there. Returns metadata plus the number of bytes written.
export async function httpGetToFile(url, opts) {
  const {
    destTmp,
    start = 0,
    end = null,
    ifRange = null,
    limiter = null,
    idleTimeoutMs = 30000,
    attemptTimeoutMs = 180000,
    headers: extraHeaders = {},
    metaOnly = false,
    maxRedirects = 5,
    signal = null,
  } = opts;

  if (signal && signal.aborted) throw abortError();

  const headers = { 'User-Agent': 'shurik-nauka/1.0', Accept: '*/*', ...extraHeaders };
  if (end != null) {
    headers.Range = `bytes=${start}-${end}`;
    if (start > 0 && ifRange) headers['If-Range'] = ifRange;
  } else if (start > 0) {
    headers.Range = `bytes=${start}-`;
    if (ifRange) headers['If-Range'] = ifRange;
  }

  const doRequest = (target, redirectsLeft) =>
    new Promise((resolve, reject) => {
      const mod = target.protocol === 'http:' ? http : https;
      let settled = false;
      const onAbort = () => {
        if (settled) return;
        settled = true;
        req.destroy(abortError());
      };
      const req = mod.request(
        target,
        { method: 'GET', headers: { ...headers, Host: target.host } },
        (res) => {
          const status = res.statusCode;
          if (status >= 300 && status < 400 && res.headers.location && redirectsLeft > 0) {
            res.resume();
            const next = new URL(res.headers.location, target);
            resolve(doRequest(next, redirectsLeft - 1));
            return;
          }
          resolve({ res, finalUrl: target.toString() });
        },
      );
      const cleanup = () => {
        settled = true;
        if (signal) signal.removeEventListener('abort', onAbort);
      };
      if (signal) signal.addEventListener('abort', onAbort, { once: true });
      req.on('close', cleanup);
      req.setTimeout(idleTimeoutMs, () => req.destroy(new Error(`idle timeout after ${idleTimeoutMs}ms`)));
      req.on('error', reject);
      req.end();
    });

  let timer;
  const attemptDeadline = Date.now() + attemptTimeoutMs;
  const overall = new Promise((_, reject) => {
    timer = setTimeout(
      () => reject(new TransientError(`attempt timeout after ${attemptTimeoutMs}ms`)),
      attemptTimeoutMs,
    );
    timer.unref?.();
  });

  let res;
  let finalUrl;
  try {
    const r = await Promise.race([doRequest(new URL(url), maxRedirects), overall]);
    res = r.res;
    finalUrl = r.finalUrl;
  } catch (err) {
    if (err && err.aborted) throw err;
    throw err instanceof TransientError ? err : new TransientError(`request failed: ${err.message}`);
  } finally {
    clearTimeout(timer);
  }
  if (signal && signal.aborted) {
    res.destroy();
    throw abortError();
  }

  const status = res.statusCode;
  const meta = {
    status,
    finalUrl,
    headers: res.headers,
    etag: res.headers.etag,
    lastModified: res.headers['last-modified'],
    contentRange: parseContentRange(res.headers['content-range']),
    contentLength: res.headers['content-length'] ? Number(res.headers['content-length']) : null,
    bytesWritten: 0,
  };

  const finish = (bytesWritten) => {
    meta.bytesWritten = bytesWritten;
    return meta;
  };

  if (status === 429 || (status >= 500 && status < 600)) {
    res.resume();
    throw new TransientError(`HTTP ${status}`, { status, retryAfterMs: retryAfterToMs(res.headers) });
  }
  if (status === 416) {
    res.resume();
    throw new RangeNotSatisfiableError('HTTP 416');
  }
  if (status === 200 && start > 0) {
    // Range ignored: do not write this body onto a partial.
    res.resume();
    throw new RangeIgnoredError('server returned 200 for a ranged request');
  }
  if (status !== 200 && status !== 206) {
    res.resume();
    throw new PermanentError(`unexpected HTTP ${status}`, status);
  }
  if (status === 206) {
    if (start > 0 && (!meta.contentRange || meta.contentRange.start !== start)) {
      res.resume();
      throw new RangeMismatchError(
        `Content-Range start ${meta.contentRange ? meta.contentRange.start : 'missing'} != ${start}`,
      );
    }
    if (end != null && meta.contentRange && meta.contentRange.end > end) {
      res.resume();
      throw new RangeMismatchError('Content-Range end beyond requested end');
    }
  }
  if (!destTmp || metaOnly) {
    res.destroy();
    return finish(0);
  }

  // The overall per-attempt timeout must cover body streaming too, not just the
  // response headers: a server that trickles bytes would otherwise keep a
  // writer alive past the batch deadline.
  const remaining = attemptDeadline - Date.now();
  if (remaining <= 0) {
    res.destroy();
    throw new TransientError(`attempt timeout after ${attemptTimeoutMs}ms`);
  }
  let bodyTimedOut = false;
  const bodyTimer = setTimeout(() => {
    bodyTimedOut = true;
    res.destroy(new Error('attempt timeout during body'));
  }, remaining);
  bodyTimer.unref?.();

  const out = createWriteStream(destTmp, { flags: 'w' });
  let written = 0;
  let failed = null;
  let streamError = null;
  out.on('error', (e) => {
    streamError = e;
  });
  try {
    for await (const chunk of res) {
      if (signal && signal.aborted) throw abortError();
      if (limiter) await limiter.take(chunk.length);
      if (signal && signal.aborted) throw abortError();
      if (!out.write(chunk)) {
        await new Promise((r) => out.once('drain', r));
      }
      if (streamError) throw streamError;
      written += chunk.length;
    }
    await new Promise((resolve, reject) => out.end((err) => (err ? reject(err) : resolve())));
  } catch (err) {
    failed = signal && signal.aborted
      ? abortError()
      : bodyTimedOut
        ? new TransientError(`attempt timeout after ${attemptTimeoutMs}ms`)
        : err;
    out.destroy();
    res.destroy();
  } finally {
    clearTimeout(bodyTimer);
  }
  if (failed) {
    // The caller removes the incomplete .tmp; the chunk model never keeps it.
    if (failed.aborted) throw failed;
    throw new TransientError(`body stream failed after ${written} bytes: ${failed.message}`);
  }
  return finish(written);
}

export async function fileExists(p) {
  try {
    await fs.stat(p);
    return true;
  } catch {
    return false;
  }
}

// GHCR publication via ORAS. ORAS is fetched into git-ignored data/ on demand.

import { execFile } from 'node:child_process';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { REPO_ROOT, PATHS, REGISTRY, SOURCE_REPO, ARTIFACT_TYPE, CHECKPOINT_ARTIFACT_TYPE } from './config.mjs';

const ORAS_VERSION = '1.2.0';
const TOOLS_DIR = path.join(REPO_ROOT, 'data/nauka/tools');

// Track every spawned child so a cancelled tool call never orphans an oras
// process holding a network connection or a staging file open.
const activeChildren = new Set();
export function killActiveChildren(signal = 'SIGTERM') {
  for (const child of activeChildren) {
    try {
      child.kill(signal);
    } catch {
      /* already gone */
    }
  }
}

function run(cmd, args, opts = {}) {
  return new Promise((resolve, reject) => {
    const child = execFile(
      cmd,
      args,
      { maxBuffer: 64 * 1024 * 1024, ...opts },
      (err, stdout, stderr) => {
        if (err) {
          err.stdout = stdout;
          err.stderr = stderr;
          reject(err);
        } else {
          resolve({ stdout, stderr });
        }
      },
    );
    activeChildren.add(child);
    const done = () => activeChildren.delete(child);
    child.on('close', done);
    child.on('error', done);
    if (opts.stdin) {
      child.stdin.end(opts.stdin);
    }
  });
}

export async function ensureOras({ log = () => {} } = {}) {
  // Prefer a system oras.
  try {
    await run('oras', ['version']);
    return 'oras';
  } catch {
    /* fall through */
  }
  const local = path.join(TOOLS_DIR, 'oras');
  try {
    await run(local, ['version']);
    return local;
  } catch {
    /* need to download */
  }
  await fs.mkdir(TOOLS_DIR, { recursive: true });
  const arch = process.arch === 'arm64' ? 'arm64' : 'amd64';
  const url = `https://github.com/oras-project/oras/releases/download/v${ORAS_VERSION}/oras_${ORAS_VERSION}_linux_${arch}.tar.gz`;
  const tgz = path.join(TOOLS_DIR, 'oras.tgz');
  log(`downloading oras ${ORAS_VERSION} from release`);
  await run('curl', ['-sSL', '-o', tgz, url], { maxBuffer: 1024 * 1024 });
  await run('tar', ['-xzf', tgz, '-C', TOOLS_DIR, 'oras']);
  await fs.chmod(local, 0o755);
  await run(local, ['version']);
  return local;
}

export class Ghcr {
  constructor({ oras, log = () => {} }) {
    this.oras = oras;
    this.log = log;
  }

  static async create(opts) {
    const oras = await ensureOras(opts);
    return new Ghcr({ oras, ...opts });
  }

  async login() {
    const user = process.env.GHCR_USERNAME;
    const token = process.env.GITHUB_TOKEN;
    if (!user || !token) throw new Error('GHCR_USERNAME / GITHUB_TOKEN are required');
    // Token is passed on stdin only; never argv or logs.
    const child = execFile(this.oras, ['login', 'ghcr.io', '-u', user, '--password-stdin'], {
      maxBuffer: 8 * 1024 * 1024,
    });
    await new Promise((resolve, reject) => {
      child.on('error', reject);
      child.on('close', (code) => (code === 0 ? resolve() : reject(new Error(`oras login exited ${code}`))));
      child.stdin.end(token);
    });
    this.log('oras login ok');
  }

  async resolve(tag) {
    const ref = `${REGISTRY}:${tag}`;
    const { stdout } = await run(this.oras, ['resolve', ref]);
    return stdout.trim();
  }

  async manifest(tag) {
    const ref = `${REGISTRY}:${tag}`;
    const { stdout } = await run(this.oras, ['manifest', 'fetch', ref]);
    return JSON.parse(stdout);
  }

  async listTags() {
    const { stdout } = await run(this.oras, ['repo', 'tags', REGISTRY]);
    return stdout
      .split(/\s+/)
      .map((s) => s.trim())
      .filter(Boolean);
  }

  // Push one file as a single layer.
  async pushFile(tag, filePath, { title, annotations = {} } = {}) {
    const dir = path.dirname(filePath);
    const base = path.basename(filePath);
    // Merge annotations so the caller cannot accidentally create a duplicate
    // key (oras rejects duplicate --annotation keys).
    const ann = {
      'org.opencontainers.image.source': SOURCE_REPO,
      'org.opencontainers.image.title': title || base,
      ...annotations,
    };
    const args = ['push', `${REGISTRY}:${tag}`, '--artifact-type', ARTIFACT_TYPE];
    for (const [k, v] of Object.entries(ann)) {
      args.push('--annotation', `${k}=${v}`);
    }
    args.push(`${base}:application/octet-stream`);
    const { stdout, stderr } = await run(this.oras, args, { cwd: dir });
    const out = `${stdout}\n${stderr}`;
    const digestMatch = /Digest:\s*(sha256:[0-9a-f]{64})/i.exec(out);
    if (!digestMatch) throw new Error(`could not parse push digest for ${tag}`);
    return { tag, digest: digestMatch[1], stdout: out };
  }

  // Push a directory tree (e.g. partial chunks) as a multi-layer checkpoint.
  async pushDir(tag, dir) {
    const args = [
      'push',
      `${REGISTRY}:${tag}`,
      '--artifact-type',
      CHECKPOINT_ARTIFACT_TYPE,
      '--annotation',
      `org.opencontainers.image.source=${SOURCE_REPO}`,
      '.',
    ];
    const { stdout, stderr } = await run(this.oras, args, { cwd: dir });
    const out = `${stdout}\n${stderr}`;
    const digestMatch = /Digest:\s*(sha256:[0-9a-f]{64})/i.exec(out);
    if (!digestMatch) throw new Error(`could not parse dir push digest for ${tag}`);
    return { tag, digest: digestMatch[1], stdout: out };
  }

  // Pull a tag or an immutable digest reference into outDir. Prefer an
  // immutable digest when a recorded checkpoint digest is available.
  async pullRef(ref, outDir) {
    await fs.mkdir(outDir, { recursive: true });
    await run(this.oras, ['pull', ref, '-o', outDir]);
    return outDir;
  }

  // Pull a tag into outDir. Returns list of files pulled.
  async pull(tag, outDir) {
    return this.pullRef(`${REGISTRY}:${tag}`, outDir);
  }
}

export { run as execFileP };

// Local HTTP fixture tests for the resumable downloader.
//
// The fixture server can: honor Range (206 + Content-Range), ignore Range
// (200 full body), drop the connection mid-body, and change its validator.
// A cold-restart test reconstructs progress from the durable partial store.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { createHash, randomBytes } from 'node:crypto';

// Tune the engine for fast, deterministic tests before importing it.
process.env.NAUKA_CHUNK = '1024';
process.env.NAUKA_CONCURRENCY = '2';
process.env.NAUKA_GAP_MS = '0';
process.env.NAUKA_BPS = '0';
process.env.NAUKA_IDLE_MS = '5000';
process.env.NAUKA_ATTEMPT_MS = '30000';
process.env.NAUKA_PASS_MS = '30000';
process.env.NAUKA_MAX_ATTEMPTS = '4';
// Isolate all state/staging under a throwaway dir so tests never clobber the
// real task checkpoint at data/nauka/state.
import os from 'node:os';
import { mkdtempSync } from 'node:fs';
process.env.NAUKA_DATA_DIR = mkdtempSync(path.join(os.tmpdir(), 'nauka-fixture-'));

const { httpGetToFile, RangeIgnoredError, TransientError } = await import('../http.mjs');
const engine = await import('../engine.mjs');
const { CONFIG, PATHS } = await import('../config.mjs');

const sha = (b) => createHash('sha256').update(b).digest('hex');
const chunkFile = (id, i) => path.join(engine.chunksDir(id), `chunk-${String(i).padStart(6, '0')}`);

function makeServer(content, opts = {}) {
  const state = { etag: opts.etag || '"v1"', dropAfter: opts.dropAfter ?? null, ignoreRange: !!opts.ignoreRange, requests: [] };
  const delayMs = opts.delayMs || 0;
  const server = http.createServer((req, res) => {
    const range = req.headers.range;
    const ifRange = req.headers['if-range'];
    const ifRangeOk = !ifRange || ifRange === state.etag;
    let start = 0;
    let end = content.length - 1;
    let status = 200;
    if (range && !state.ignoreRange && ifRangeOk) {
      const m = /bytes=(\d+)-(\d*)/.exec(range);
      if (m) {
        start = Number(m[1]);
        end = m[2] ? Number(m[2]) : content.length - 1;
        if (start >= content.length) {
          res.writeHead(416, { 'Content-Range': `bytes */${content.length}` });
          res.end();
          return;
        }
        end = Math.min(end, content.length - 1);
        status = 206;
      }
    }
    state.requests.push(range || 'full');
    const body = content.subarray(start, end + 1);
    const headers = { ETag: state.etag, 'Last-Modified': 'Wed, 01 Jan 2020 00:00:00 GMT' };
    if (status === 206) headers['Content-Range'] = `bytes ${start}-${end}/${content.length}`;
    headers['Content-Length'] = String(status === 206 ? body.length : content.length);
    const send = () => {
      res.writeHead(status, headers);
      if (state.dropAfter != null) {
        res.write(body.subarray(0, state.dropAfter));
        setTimeout(() => res.socket.destroy(), 5);
        return;
      }
      res.end(body);
    };
    if (delayMs > 0) setTimeout(send, delayMs);
    else send();
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      resolve({
        url: `http://127.0.0.1:${server.address().port}/file.bin`,
        state,
        close: () => new Promise((r) => server.close(r)),
      });
    });
  });
}

// A server that announces a correct Content-Range/Length but only ever writes
// part of the body, so a writer is guaranteed to have an open .tmp file when
// the batch is cancelled.
function makeTrickleServer(content) {
  const server = http.createServer((req, res) => {
    const m = /bytes=(\d+)-(\d*)/.exec(req.headers.range || '');
    const start = m ? Number(m[1]) : 0;
    const end = m && m[2] ? Math.min(Number(m[2]), content.length - 1) : content.length - 1;
    res.writeHead(206, {
      ETag: '"v1"',
      'Content-Range': `bytes ${start}-${end}/${content.length}`,
      'Content-Length': String(end - start + 1),
    });
    res.write(content.subarray(start, start + 50));
    // deliberately never end the response
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      resolve({
        url: `http://127.0.0.1:${server.address().port}/file.bin`,
        close: () => new Promise((r) => server.close(r)),
      });
    });
  });
}

// Run fn with a fixture server that is always closed afterwards.
async function withServer(content, opts, fn) {
  const srv = await makeServer(content, opts);
  try {
    return await fn(srv);
  } finally {
    await srv.close();
  }
}

async function tmpPath(name) {
  const dir = path.join(PATHS.stagingDir, 'test', `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  await fs.mkdir(dir, { recursive: true });
  return path.join(dir, name);
}

function makeCtx(state, entry, fakeGhcr) {
  return {
    state,
    manifest: { entries: [entry], indexUrl: 'http://example/index' },
    log: () => {},
    limiter: { take: async () => {} },
    pool: engine.createPool(2),
    ghcr: fakeGhcr,
  };
}

test('honors Range and returns correct 206 bytes', async () => {
  const content = randomBytes(5000);
  await withServer(content, {}, async (srv) => {
    const dest = await tmpPath('a.bin');
    const meta = await httpGetToFile(srv.url, { destTmp: dest, start: 1000, end: 1999 });
    assert.equal(meta.status, 206);
    assert.equal(meta.contentRange.start, 1000);
    assert.equal(meta.contentRange.total, 5000);
    assert.deepEqual(await fs.readFile(dest), content.subarray(1000, 2000));
  });
});

test('detects an ignored Range and never appends a full response', async () => {
  const content = randomBytes(5000);
  await withServer(content, { ignoreRange: true }, async (srv) => {
    const dest = await tmpPath('partial.bin');
    await fs.writeFile(dest, Buffer.from('EXISTING-PARTIAL'));
    await assert.rejects(
      () => httpGetToFile(srv.url, { destTmp: dest, start: 1000, end: 1999 }),
      RangeIgnoredError,
    );
    assert.equal((await fs.readFile(dest)).toString(), 'EXISTING-PARTIAL');
  });
});

test('retries after a mid-body connection drop', async () => {
  const content = randomBytes(4000);
  await withServer(content, { dropAfter: 500 }, async (srv) => {
    const dest = await tmpPath('drop.bin');
    await assert.rejects(
      () => httpGetToFile(srv.url, { destTmp: dest, start: 0, end: 3999 }),
      TransientError,
    );
    srv.state.dropAfter = null;
    const meta = await httpGetToFile(srv.url, { destTmp: dest, start: 0, end: 3999 });
    assert.equal(meta.bytesWritten, 4000);
    assert.deepEqual(await fs.readFile(dest), content);
  });
});

test('detects a changed validator and resets progress', async () => {
  const content = randomBytes(4096);
  await withServer(content, { etag: '"v1"' }, async (srv) => {
    const entry = {
      id: 'fx-valid',
      year: 1934,
      issue: 'N01',
      format: 'djv',
      filename: 'fx.bin',
      url: srv.url,
      labelText: 'fx',
      labelSize: '1M',
    };
    const state = { version: 1, files: {} };
    const eff = engine.ensureFileEntry(state, entry);
    eff.expectedBytes = content.length;
    eff.etag = '"v1"';
    eff.status = 'in_progress';
    // Seed chunk 0 as already downloaded under etag v1.
    await fs.mkdir(engine.chunksDir(entry.id), { recursive: true });
    const c0 = content.subarray(0, CONFIG.chunkSize);
    await fs.writeFile(chunkFile(entry.id, 0), c0);
    eff.chunks[0] = { bytes: c0.length, sha256: sha(c0) };

    // Origin validator changes; the next ranged chunk must be rejected.
    srv.state.etag = '"v2"';
    const r = await engine.downloadFile(makeCtx(state, entry, null), entry);
    assert.equal(r.done, false);
    assert.equal(Object.keys(eff.chunks).length, 0, 'chunks must be reset after validator change');
    assert.match(String(eff.lastError), /validator/);
  });
});

test('cold restart reconstructs progress from git partial and GHCR checkpoint', async () => {
  const content = randomBytes(8192);
  await withServer(content, {}, async (srv) => {
    const entry = {
      id: 'fx-cold',
      year: 1939,
      issue: 'N01',
      format: 'djv',
      filename: 'fx-cold.bin',
      url: srv.url,
      labelText: 'fx',
      labelSize: '1M',
    };

    const state = { version: 1, files: {} };
    const eff = engine.ensureFileEntry(state, entry);
    eff.expectedBytes = content.length;
    eff.chunkSize = CONFIG.chunkSize;
    eff.status = 'in_progress';
    await fs.mkdir(engine.chunksDir(entry.id), { recursive: true });
    for (let i = 0; i < 2; i++) {
      const buf = content.subarray(i * CONFIG.chunkSize, (i + 1) * CONFIG.chunkSize);
      await fs.writeFile(chunkFile(entry.id, i), buf);
      eff.chunks[i] = { bytes: buf.length, sha256: sha(buf) };
    }
    eff.receivedBytes = 2048;

    const fakeGhcr = makeFakeGhcr();
    const ctx = makeCtx(state, entry, fakeGhcr);

    await engine.checkpointPartials(ctx);
    assert.ok(fakeGhcr.store.has(`checkpoint-${entry.id}`), 'checkpoint pushed to GHCR');

    // Fresh runner: wipe local stage bytes, keep state.
    await fs.rm(engine.workspaceDir(entry.id), { recursive: true, force: true });

    const n = await engine.restoreFromGitPartials(state, () => {});
    assert.ok(n >= 2, `expected >=2 restored chunks, got ${n}`);

    await engine.restoreFromCheckpoints(ctx);

    const r = await engine.downloadFile(ctx, entry);
    assert.equal(r.done, true);
    const assembled = await engine.assembleHex(eff);
    assert.equal(assembled.bytes, content.length);
    assert.equal(assembled.sha256, sha(content));
  });
});

