      await fs.writeFile(chunkFile(small.id, i), buf);
      effSmall.chunks[i] = { bytes: buf.length, sha256: sha(buf) };
    }
    effSmall.receivedBytes = Object.values(effSmall.chunks).reduce((a, c) => a + c.bytes, 0);

    const ctx = {
