```js
import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { spawn } from 'node:child_process';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash, randomBytes } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const CLI = path.resolve(HERE, '..', 'cli.mjs');
const CHUNK = 65536;

const sha = (b) => createHash('sha256').update(b).digest('hex');

function serveRange(content, { etag = '"v1"', trickle = false } = {}) {
  const requests = [];
  const server = http.createServer((req, res) => {
    const range = req.headers.range || '';
    const m = /bytes=(\d+)-(\d*)/.exec(range);
    const start = m ? Number(m[1]) : 0;
    const end = m && m[2] ? Math.min(Number(m[2]), content.length - 1) : content.length - 1;
    requests.push(range || 'full');
    const body = content.subarray(start, end + 1);
    const headers = {
      ETag: etag,
      'Last-Modified': 'Wed, 01 Jan 2020 00:00:00 GMT',
      'Content-Range': `bytes ${start}-${end}/${content.length}`,
      'Content-Length': String(body.length),
    };
    res.writeHead(206, headers);
    if (trickle) {
      res.write(body.subarray(0, Math.min(64, body.length)));
      // never end: keep the writer open so preemption has a live .tmp
    } else {
      res.end(body);
    }
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => resolve({
      url: `http://127.0.0.1:${server.address().port}/fx.bin`,
      requests,
      close: () => new Promise((r) => server.close(r)),
    }));
  });
}
```

Wait: with trickle and no res.end, when the client aborts, the server socket closes. server.close() waits for connections to close; the aborted ones close. Should be ok.

