```js
function spawnRetrieve(dataDir, extraArgs = [], extraEnv = {}) {
  const child = spawn(process.execPath, [CLI, 'retrieve', ...extraArgs], {
    env: {
      ...process.env,
      NAUKA_DATA_DIR: dataDir,
      NAUKA_GHCR_FAKE: '1',
      NAUKA_CHUNK: String(CHUNK),
      NAUKA_CONCURRENCY: '2',
      NAUKA_GAP_MS: '0',
      NAUKA_BPS: '0',
      NAUKA_FILE_CONCURRENCY: '1',
      NAUKA_IDLE_MS: '60000',
      NAUKA_ATTEMPT_MS: '60000',
      NAUKA_MIN_CHUNK_MS: '200',
      NAUKA_PUBLISH_RESERVE_MS: '200',
      ...extraEnv,
    },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let out = '';
  child.stdout.on('data', (d) => (out += d));
  child.stderr.on('data', (d) => (out += d));
  return { child, getOutput: () => out };
}
